class UploadQuota:
    def __init__(self, monthly_limit_mib: float) -> None:
        self.monthly_limit_bytes = int(monthly_limit_mib * 1024 * 1024)
        # Tracks current files uploaded per month: month -> {name: size_bytes}
        self._files: dict[str, dict[str, int]] = {}
        # Tracks total uploaded bytes towards quota per month: month -> int
        self._used_bytes: dict[str, int] = {}

    def upload(self, name: str, size_bytes: int, month: str) -> None:
        """month is a string like "2026-01"."""
        if size_bytes <= 0:
            raise ValueError("File size must be greater than 0 bytes.")

        month_files = self._files.setdefault(month, {})
        current_used = self._used_bytes.get(month, 0)

        # If a file with the same name was already uploaded in this month,
        # it does not count towards the quota again.
        if name in month_files:
            return

        if current_used + size_bytes > self.monthly_limit_bytes:
            raise ValueError("Upload would exceed monthly quota limit.")

        month_files[name] = size_bytes
        self._used_bytes[month] = current_used + size_bytes

    def delete(self, name: str, month: str) -> None:
        """Deleting a file does not give back quota in the month."""
        month_files = self._files.get(month)
        if month_files and name in month_files:
            del month_files[name]

    def used_bytes(self, month: str) -> int:
        """How many bytes count towards the quota in the given month."""
        return self._used_bytes.get(month, 0)
